import math

def ceil_div(a, b):
    return (a + b - 1) // b

def solveL(v, v1, s, k):
    n = len(v) + 1
    if k == 1:
        return max(0, ceil_div(s - 2 * v1, n - 1))
    v.sort(reverse=True)
    vk = v[k - 2]
    z = max(ceil_div(s - v1 - vk, n - 2), ceil_div(s - 2 * v1, n - 1))
    if min(z, (n - 2) * z - s + 2 * vk) >= max(0, s - (n - 2) * z - 2 * v1):
        return z
    return math.inf

